import React, { useState } from "react";
import axios from "axios";
import "./Auth.css";

const Register = () => {

const [form,setForm]=useState({

name:"",

email:"",

password:"",

role:"Student",

otp:""

});

const [msg,setMsg]=useState("");

const handleChange=(e)=>{

setForm({

...form,

[e.target.name]:e.target.value

});

};



const sendOtp = async () => {

try{

const res = await axios.post(

"http://localhost:5000/api/auth/send-otp",

{

email: form.email

}

);

setMsg(

"Your OTP : " +

res.data.otp

);

}

catch(err){

setMsg("OTP Failed ❌");

}

};



const handleSubmit=async(e)=>{

e.preventDefault();

try{

const res=await axios.post(

"http://localhost:5000/api/auth/register",

form

);

setMsg(

res.data.message

);

}

catch(err){

setMsg(

err.response?.data?.message

||

"Registration Failed"

);

}

};



return(

<div className="auth-container">

<div className="auth-card">

<h1>

Create Account

</h1>

<p>

Register to RBAC System

</p>



<form onSubmit={handleSubmit}>



<input

type="text"

name="name"

placeholder="Full Name"

onChange={handleChange}

required

/>



<input

type="email"

name="email"

placeholder="Email"

onChange={handleChange}

required

/>



<div className="otp-box">

<input

type="text"

name="otp"

placeholder="Enter OTP"

onChange={handleChange}

/>



<button

type="button"

className="otp-btn"

onClick={sendOtp}

>

Send OTP

</button>

</div>



<input

type="password"

name="password"

placeholder="Password"

onChange={handleChange}

required

/>



<select

name="role"

onChange={handleChange}

>

<option>

Student

</option>

<option>

Instructor

</option>

<option>

Admin

</option>

</select>



<button

className="main-btn"

type="submit"

>

Register

</button>



</form>



<h4>

{msg}

</h4>



</div>

</div>

)

}

export default Register;
